func CreateWithin(parent context.Context, budget time.Duration,
	create func(context.Context) (string, error),
) (string, error) {
	ctx, cancel := context.WithTimeout(parent, budget)
	defer cancel()
	if err := ctx.Err(); err != nil {
		return "", err
	}
	id, err := create(ctx)
	if err != nil {
		return "", err
	}
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return id, nil
}

