func Count(ctx context.Context) (<-chan int, <-chan struct{}) {
	out := make(chan int)
	exited := make(chan struct{})
	go func() {
		defer close(exited)
		defer close(out)
		for n := 0; ; n++ {
			select {
			case <-ctx.Done():
				return
			case out <- n:
			}
		}
	}()
	return out, exited
}
